<?php require __DIR__.'/includes/bootstrap.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$nom=trim($_POST['nom']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$tel=trim($_POST['telephone']??'');$pw=$_POST['password']??'';if(!$nom||!$email||strlen($pw)<10){$error='Renseignez un nom, un email valide et un mot de passe de 10 caractères minimum.';}else{try{$s=$pdo->prepare('INSERT INTO users(nom,email,password,telephone) VALUES(?,?,?,?)');$s->execute([$nom,$email,password_hash($pw,PASSWORD_DEFAULT),$tel]);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$pdo->lastInsertId(),'nom'=>$nom,'email'=>$email,'role'=>'client'];redirect('/dashboard.php');}catch(PDOException $e){$error='Cette adresse email est déjà utilisée.';}}}$title='Créer un compte';require __DIR__.'/includes/header.php';?>
<section class="auth-layout"><aside class="auth-panel"><div><p class="uppercase tracking-[.2em] text-teal-100 text-xs font-bold">Bienvenue chez Voyalo</p><h1 class="text-3xl font-black mt-3">Votre prochaine aventure est à portée de main.</h1><p class="text-teal-100 mt-3">Créez un compte pour réserver, payer avec Mobile Money et garder tous vos billets à portée de main.</p></div><div class="auth-decoration"><span class="inline-flex rounded-full bg-white/15 px-4 py-2">Hôtels · Billets · Circuits</span></div></aside><div class="auth-form"><p class="page-eyebrow">Compte voyageur</p><h2 class="text-2xl font-black mt-1">Créer mon compte</h2><p class="text-sm text-slate-600 mt-2">Quelques informations pour commencer.</p><?php if($error):?><p class="mt-4 bg-rose-50 text-rose-800 p-3 rounded-lg" role="alert"><?=e($error)?></p><?php endif;?><form method="post" class="mt-6 space-y-4"><?=csrf_field()?><div><label>Nom complet</label><input name="nom" required maxlength="120" autocomplete="name" placeholder="Votre nom"></div><div><label>Adresse email</label><input type="email" name="email" required autocomplete="email" placeholder="vous@exemple.com"></div><div><label>Téléphone <span class="font-normal text-slate-500">(facultatif)</span></label><input name="telephone" autocomplete="tel" placeholder="6XX XXX XXX"></div><div><label>Mot de passe</label><input type="password" name="password" minlength="10" required autocomplete="new-password" placeholder="10 caractères minimum"><p class="text-xs text-slate-500 mt-1">Utilisez au moins 10 caractères.</p></div><button class="btn w-full">Créer mon compte</button></form><p class="mt-5 text-sm text-center text-slate-600">Déjà inscrit ? <a class="text-teal-800 font-bold underline" href="/login.php">Se connecter</a></p></div></section><?php require __DIR__.'/includes/footer.php';?>
